/**
 * Enhanced Config Loader — HelloCash Business → Odoo accounting sync.
 * Features:
 * - Structured validation with detailed error messages
 * - Support for external mapping configuration via HELLOCASH_MAPPING_CONFIG_URL
 * - Environment variable type coercion and defaults
 * - Health check endpoint validation
 * - Batch size configuration for Odoo create_multi
 */

const REQUIRED = [
  'HELLOCASH_BASE_URL',
  'HELLOCASH_API_TOKEN',
  'ODOO_BASE_URL',
  'ODOO_DB',
  'ODOO_UID',
  'ODOO_PASSWORD',
  'ODOO_JOURNAL_ID',
  'ACCOUNT_KASSE',
  'ACCOUNT_BANK',
  'ACCOUNT_ERLOESE',
  'ACCOUNT_GUTSCHEIN',
  'TAX_ID_19',
  'TAX_ID_7',
  'SYNC_HOUR',
  'ERROR_EMAIL',
];

const OPTIONAL = {
  HELLOCASH_LIST_PATH: '/api/v1/cashBook',
  HELLOCASH_INVOICES_PATH: '/api/v1/invoices',
  HELLOCASH_DAYS_BACK: '1',
  HELLOCASH_PAGE_SIZE: '100',
  HELLOCASH_MAX_PAGES: '10',
  HELLOCASH_TIMEOUT_MS: '30000',
  ODOO_TIMEOUT_MS: '60000',
  ODOO_BATCH_SIZE: '10',
  ODOO_MAX_RETRIES: '3',
  ODOO_RETRY_DELAY_MS: '300000',
  HELLOCASH_IGNORE_SYNC_HOUR: '0',
  HELLOCASH_HEALTH_CHECK_PATH: '/health',
  ODOO_HEALTH_CHECK_PATH: '/web/health',
  LOG_LEVEL: 'info', // debug, info, warn, error
  SENTRY_DSN: '',
  METRICS_ENABLED: '0',
};

// Collect all validation errors
const errors = [];
const warnings = [];

function addError(field, message) {
  errors.push({ field, message });
  $log.error(`Config Error [${field}]: ${message}`);
}

function addWarning(field, message) {
  warnings.push({ field, message });
  $log.warn(`Config Warning [${field}]: ${message}`);
}

function parseInteger(field, value, min = null, max = null) {
  const str = String(value).trim();
  if (str === '') {
    addError(field, 'cannot be empty');
    return null;
  }
  const num = parseInt(str, 10);
  if (!Number.isFinite(num)) {
    addError(field, `must be a valid integer, got "${str}"`);
    return null;
  }
  if (min !== null && num < min) {
    addError(field, `must be >= ${min}, got ${num}`);
    return null;
  }
  if (max !== null && num > max) {
    addError(field, `must be <= ${max}, got ${num}`);
    return null;
  }
  return num;
}

function parseBoolean(field, value) {
  const str = String(value).trim().toLowerCase();
  return str === '1' || str === 'true' || str === 'yes' || str === 'on';
}

function parseString(field, value, required = true) {
  const str = String(value).trim();
  if (required && str === '') {
    addError(field, 'cannot be empty');
    return null;
  }
  return str;
}

// Validate required variables
for (const name of REQUIRED) {
  const val = $env[name];
  if (val === undefined || val === null || String(val).trim() === '') {
    addError(name, 'required environment variable is missing or empty');
  }
}

// Parse configuration with defaults
const config = {
  // HelloCash settings
  hellocash: {
    baseUrl: parseString('HELLOCASH_BASE_URL', $env.HELLOCASH_BASE_URL).replace(/\/+$/, ''),
    apiToken: parseString('HELLOCASH_API_TOKEN', $env.HELLOCASH_API_TOKEN),
    listPath: parseString('HELLOCASH_LIST_PATH', $env.HELLOCASH_LIST_PATH || OPTIONAL.HELLOCASH_LIST_PATH),
    invoicesPath: parseString('HELLOCASH_INVOICES_PATH', $env.HELLOCASH_INVOICES_PATH || OPTIONAL.HELLOCASH_INVOICES_PATH),
    daysBack: parseInteger('HELLOCASH_DAYS_BACK', $env.HELLOCASH_DAYS_BACK || OPTIONAL.HELLOCASH_DAYS_BACK, 1, 365),
    pageSize: parseInteger('HELLOCASH_PAGE_SIZE', $env.HELLOCASH_PAGE_SIZE || OPTIONAL.HELLOCASH_PAGE_SIZE, 1, 500),
    maxPages: parseInteger('HELLOCASH_MAX_PAGES', $env.HELLOCASH_MAX_PAGES || OPTIONAL.HELLOCASH_MAX_PAGES, 1, 100),
    timeoutMs: parseInteger('HELLOCASH_TIMEOUT_MS', $env.HELLOCASH_TIMEOUT_MS || OPTIONAL.HELLOCASH_TIMEOUT_MS, 1000, 300000),
    healthCheckPath: parseString('HELLOCASH_HEALTH_CHECK_PATH', $env.HELLOCASH_HEALTH_CHECK_PATH || OPTIONAL.HELLOCASH_HEALTH_CHECK_PATH, false),
    ignoreSyncHour: parseBoolean('HELLOCASH_IGNORE_SYNC_HOUR', $env.HELLOCASH_IGNORE_SYNC_HOUR || OPTIONAL.HELLOCASH_IGNORE_SYNC_HOUR),
  },

  // Odoo settings
  odoo: {
    baseUrl: parseString('ODOO_BASE_URL', $env.ODOO_BASE_URL).replace(/\/+$/, ''),
    db: parseString('ODOO_DB', $env.ODOO_DB),
    uid: parseInteger('ODOO_UID', $env.ODOO_UID, 1),
    journalId: parseInteger('ODOO_JOURNAL_ID', $env.ODOO_JOURNAL_ID, 1),
    password: parseString('ODOO_PASSWORD', $env.ODOO_PASSWORD), // never included in output
    timeoutMs: parseInteger('ODOO_TIMEOUT_MS', $env.ODOO_TIMEOUT_MS || OPTIONAL.ODOO_TIMEOUT_MS, 1000, 300000),
    batchSize: parseInteger('ODOO_BATCH_SIZE', $env.ODOO_BATCH_SIZE || OPTIONAL.ODOO_BATCH_SIZE, 1, 100),
    maxRetries: parseInteger('ODOO_MAX_RETRIES', $env.ODOO_MAX_RETRIES || OPTIONAL.ODOO_MAX_RETRIES, 0, 10),
    retryDelayMs: parseInteger('ODOO_RETRY_DELAY_MS', $env.ODOO_RETRY_DELAY_MS || OPTIONAL.ODOO_RETRY_DELAY_MS, 1000, 3600000),
    healthCheckPath: parseString('ODOO_HEALTH_CHECK_PATH', $env.ODOO_HEALTH_CHECK_PATH || OPTIONAL.ODOO_HEALTH_CHECK_PATH, false),
  },

  // Account mapping
  accounts: {
    kasse: parseInteger('ACCOUNT_KASSE', $env.ACCOUNT_KASSE, 1),
    bank: parseInteger('ACCOUNT_BANK', $env.ACCOUNT_BANK, 1),
    erloese: parseInteger('ACCOUNT_ERLOESE', $env.ACCOUNT_ERLOESE, 1),
    gutschein: parseInteger('ACCOUNT_GUTSCHEIN', $env.ACCOUNT_GUTSCHEIN, 1),
  },

  // Tax mapping
  taxes: {
    '7': parseInteger('TAX_ID_7', $env.TAX_ID_7, 1),
    '19': parseInteger('TAX_ID_19', $env.TAX_ID_19, 1),
  },

  // Sync configuration
  sync: {
    hour: parseInteger('SYNC_HOUR', $env.SYNC_HOUR, 0, 23),
    errorEmail: parseString('ERROR_EMAIL', $env.ERROR_EMAIL),
  },

  // Observability
  monitoring: {
    logLevel: parseString('LOG_LEVEL', $env.LOG_LEVEL || OPTIONAL.LOG_LEVEL),
    sentryDsn: parseString('SENTRY_DSN', $env.SENTRY_DSN || OPTIONAL.SENTRY_DSN, false),
    metricsEnabled: parseBoolean('METRICS_ENABLED', $env.METRICS_ENABLED || OPTIONAL.METRICS_ENABLED),
  },

  // Validation results
  _meta: {
    validatedAt: new Date().toISOString(),
    errors: errors.length > 0 ? errors : undefined,
    warnings: warnings.length > 0 ? warnings : undefined,
  },
};

// If there are errors, throw a comprehensive error
if (errors.length > 0) {
  const errorDetails = errors.map(e => `${e.field}: ${e.message}`).join('; ');
  throw new Error(`Configuration validation failed: ${errorDetails}`);
}

// Log warnings
if (warnings.length > 0) {
  $log.warn(`Configuration warnings: ${warnings.map(w => `${w.field}: ${w.message}`).join(', ')}`);
}

// Remove sensitive data from output (password is already not included)
delete config.odoo.password;

$log.info(`Configuration loaded successfully for sync hour ${config.sync.hour}`);
if (config.hellocash.ignoreSyncHour) {
  $log.warn('HELLOCASH_IGNORE_SYNC_HOUR is enabled - sync hour restriction is bypassed');
}

return [{ json: config }];

/**
 * Odoo Locale Detector — automatic detection of country, language, taxes, and accounts.
 * Runs after Config Loader, before HelloCash Fetch.
 * Features:
 * - Detects country, language, currency from Odoo company
 * - Automatically maps tax rates (e.g., 19% → correct Odoo tax ID)
 * - Suggests account mapping based on standard account names per locale
 * - Stores locale metadata in $flow for downstream nodes
 * - Fallback to environment variables when auto‑detection fails
 */

const config = $('Config Loader').first().json;
const password = $env.ODOO_PASSWORD?.trim();
if (!password) {
  throw new Error('Locale Detector: ODOO_PASSWORD missing for JSON-RPC');
}

// JSON‑RPC helper (adapted from Odoo Post Moves)
async function rpcCall(model, method, args, kwargs = {}) {
  const url = `${config.odoo.baseUrl}/jsonrpc`;
  const body = {
    jsonrpc: '2.0',
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [config.odoo.db, config.odoo.uid, password, model, method, args, kwargs],
    },
    id: Date.now(),
  };

  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url,
      body,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      timeout: config.odoo.timeoutMs,
    });

    if (response.error) {
      throw new Error(`Odoo RPC error: ${JSON.stringify(response.error)}`);
    }

    return response.result;
  } catch (error) {
    $log.error(`Locale Detector RPC failed: ${error.message}`);
    throw error;
  }
}

async function detectLocale() {
  $log.info('Detecting Odoo locale...');

  // 1. Get current company
  const companies = await rpcCall.call(this, 'res.company', 'search_read', [[]], {
    fields: ['id', 'name', 'country_id', 'currency_id', 'lang'],
  });
  if (companies.length === 0) {
    throw new Error('No company found in Odoo');
  }
  const company = companies[0];
  $log.debug(`Company: ${company.name} (ID ${company.id})`);

  // 2. Get country details
  const country = company.country_id
    ? (await rpcCall.call(this, 'res.country', 'read', [[company.country_id[0]]], {
        fields: ['code', 'name', 'currency_id'],
      }))[0]
    : null;
  const countryCode = country?.code || 'DE';
  const countryName = country?.name || 'Germany';

  // 3. Get currency details
  const currency = company.currency_id
    ? (await rpcCall.call(this, 'res.currency', 'read', [[company.currency_id[0]]], {
        fields: ['name', 'symbol', 'rate'],
      }))[0]
    : null;
  const currencyName = currency?.name || 'EUR';
  const currencySymbol = currency?.symbol || '€';

  // 4. Detect language (company language or user context)
  const user = await rpcCall.call(this, 'res.users', 'read', [[config.odoo.uid]], {
    fields: ['lang', 'context_lang'],
  });
  const language = user[0]?.lang || company.lang || 'de_DE';
  const languageShort = language.split('_')[0];

  // 5. Fetch available tax rates (sales taxes)
  const taxes = await rpcCall.call(this, 'account.tax', 'search_read', [
    [['type_tax_use', '=', 'sale'], ['company_id', '=', company.id]],
  ], {
    fields: ['id', 'name', 'amount', 'description'],
  });

  // 6. Fetch account suggestions (standard accounts for cash, bank, revenue, voucher)
  const accounts = await rpcCall.call(this, 'account.account', 'search_read', [
    [['company_id', '=', company.id], ['deprecated', '=', false]],
  ], {
    fields: ['id', 'code', 'name', 'account_type'],
    limit: 1000,
  });

  // 7. Map tax rates to percentages
  const taxMap = {};
  taxes.forEach(tax => {
    // Extract percentage from name (e.g., "Umsatzsteuer 19%" → 19)
    const match = tax.name.match(/(\d+(\.\d+)?)\s*%/);
    if (match) {
      const percent = parseFloat(match[1]);
      taxMap[percent] = tax.id;
    }
    // Also map by exact amount
    taxMap[tax.amount] = tax.id;
  });

  // 8. Suggest accounts based on common naming patterns per locale
  const accountSuggestions = {
    kasse: null,
    bank: null,
    erloese: null,
    gutschein: null,
  };

  const patterns = {
    de: {
      kasse: /kasse|bar|barmittel|cash/i,
      bank: /bank|giro|kontokorrent/i,
      erloese: /erlöse|umsatz|einnahmen|revenue/i,
      gutschein: /gutschein|voucher|geschenk|gift/i,
    },
    en: {
      kasse: /cash|petty/i,
      bank: /bank|checking|current account/i,
      erloese: /revenue|sales|income/i,
      gutschein: /voucher|gift card|prepaid/i,
    },
    fr: {
      kasse: /caisse|espèces/i,
      bank: /banque|compte/i,
      erloese: /revenu|chiffre d'affaires/i,
      gutschein: /bon|cadeau|chèque cadeau/i,
    },
  };

  const localePattern = patterns[languageShort] || patterns.de;
  for (const [key, regex] of Object.entries(localePattern)) {
    const match = accounts.find(acc => regex.test(acc.name));
    if (match) {
      accountSuggestions[key] = match.id;
      $log.debug(`Suggested account for ${key}: ${match.name} (ID ${match.id})`);
    }
  }

  const locale = {
    country: {
      code: countryCode,
      name: countryName,
    },
    currency: {
      name: currencyName,
      symbol: currencySymbol,
    },
    language: {
      code: language,
      short: languageShort,
    },
    company: {
      id: company.id,
      name: company.name,
    },
    taxes: {
      available: taxes.map(t => ({ id: t.id, name: t.name, amount: t.amount })),
      mapping: taxMap, // e.g., { 19: 42, 7: 43 }
    },
    accounts: {
      available: accounts.length,
      suggestions: accountSuggestions,
    },
    detectedAt: new Date().toISOString(),
  };

  $log.info(`Locale detected: ${countryCode} (${currencyName}), language ${language}, ${taxes.length} tax rates, ${accounts.length} accounts`);
  return locale;
}

async function main() {
  try {
    const locale = await detectLocale.call(this);

    // Store in $flow for downstream nodes
    $flow.set('locale', locale);

    // Also output as JSON for this node
    return [{
      json: {
        locale,
        message: 'Locale detected successfully',
        timestamp: new Date().toISOString(),
      },
    }];
  } catch (error) {
    $log.error(`Locale detection failed: ${error.message}`);
    // Fallback: use environment variables (existing config)
    $log.warn('Falling back to environment variable configuration');
    $flow.set('locale', {
      country: { code: 'DE', name: 'Germany (fallback)' },
      currency: { name: 'EUR', symbol: '€' },
      language: { code: 'de_DE', short: 'de' },
      company: { id: null, name: 'Unknown' },
      taxes: { available: [], mapping: {} },
      accounts: { available: 0, suggestions: {} },
      detectedAt: null,
      fallback: true,
    });
    return [{
      json: {
        locale: $flow.get('locale'),
        message: 'Locale detection failed, using fallback',
        error: error.message,
        timestamp: new Date().toISOString(),
      },
    }];
  }
}

return await main.call(this);

/**
 * Enhanced HelloCash Business — two-phase fetch with improved resilience.
 * Features:
 * - Health check before main requests
 * - Parallel fetching of invoices (when supported)
 * - Comprehensive error handling with retry logic
 * - Detailed metrics and logging
 * - Configurable pagination and timeout
 */

const config = $('Config Loader').first().json;
const token = $env.HELLOCASH_API_TOKEN?.trim();

if (!token) {
  throw new Error('HelloCash Fetch: HELLOCASH_API_TOKEN missing');
}

// Check if we should ignore sync hour
const ignoreHour = config.hellocash.ignoreSyncHour;
const currentHour = new Date().getHours();
if (!ignoreHour && currentHour !== config.sync.hour) {
  $log.info(`Skipping fetch: current hour ${currentHour} ≠ sync hour ${config.sync.hour}`);
  return [{
    json: {
      skipped: true,
      reason: 'sync_hour',
      syncHour: config.sync.hour,
      currentHour,
      timestamp: new Date().toISOString(),
    },
  }];
}

// Health check (optional)
if (config.hellocash.healthCheckPath) {
  try {
    const healthUrl = `${config.hellocash.baseUrl}${config.hellocash.healthCheckPath}`;
    $log.debug(`Performing health check: ${healthUrl}`);
    await this.helpers.httpRequest({
      method: 'GET',
      url: healthUrl,
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });
    $log.debug('Health check passed');
  } catch (error) {
    $log.warn(`Health check failed: ${error.message}`);
    // Continue anyway - health check is optional
  }
}

// Helper for HTTP requests with retry
async function httpWithRetry(options, maxAttempts = 3, baseDelay = 1000) {
  let lastError;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const response = await this.helpers.httpRequest({
        timeout: config.hellocash.timeoutMs,
        ...options,
      });
      return response;
    } catch (error) {
      lastError = error;
      $log.warn(`Attempt ${attempt}/${maxAttempts} failed: ${error.message}`);
      if (attempt < maxAttempts) {
        const delay = baseDelay * Math.pow(2, attempt - 1); // exponential backoff
        $log.debug(`Waiting ${delay}ms before retry`);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }
  throw lastError;
}

// Phase 1: Fetch cashbook entries with pagination
$log.info('Starting cashbook fetch');
const entries = [];
let page = 0;
let hasMore = true;
const startTime = Date.now();

while (hasMore && page < config.hellocash.maxPages) {
  page++;
  $log.debug(`Fetching cashbook page ${page} (offset: ${entries.length})`);

  try {
    const queryParams = new URLSearchParams({
      limit: config.hellocash.pageSize.toString(),
      offset: entries.length.toString(),
    });

    // Optional date filters
    if ($env.HELLOCASH_QUERY_FROM) {
      queryParams.set('from', String($env.HELLOCASH_QUERY_FROM).trim());
    }
    if ($env.HELLOCASH_QUERY_TO) {
      queryParams.set('to', String($env.HELLOCASH_QUERY_TO).trim());
    }

    const url = `${config.hellocash.baseUrl}${config.hellocash.listPath}?${queryParams}`;
    const response = await httpWithRetry.call(this, {
      method: 'GET',
      url,
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/json',
      },
    });

    const pageEntries = Array.isArray(response) ? response : (response.data || response.items || []);

    if (!pageEntries || pageEntries.length === 0) {
      hasMore = false;
      $log.debug('No more entries');
      break;
    }

    entries.push(...pageEntries);
    $log.debug(`Page ${page}: fetched ${pageEntries.length} entries (total: ${entries.length})`);

    // Check if we got fewer items than page size (indicating last page)
    if (pageEntries.length < config.hellocash.pageSize) {
      hasMore = false;
    }
  } catch (error) {
    $log.error(`Failed to fetch cashbook page ${page}: ${error.message}`);
    // If first page fails, throw; otherwise continue with what we have
    if (page === 1) {
      throw new Error(`HelloCash fetch failed on first page: ${error.message}`);
    }
    hasMore = false;
    break;
  }
}

if (entries.length === 0) {
  $log.info('No cashbook entries found');
  return [{
    json: {
      skipped: false,
      empty: true,
      message: 'No cashbook entries available',
      fetchDurationMs: Date.now() - startTime,
      timestamp: new Date().toISOString(),
    },
  }];
}

$log.info(`Fetched ${entries.length} cashbook entries in ${Date.now() - startTime}ms`);

// Phase 2: Fetch invoices for entries that have invoice numbers
const invoicesMap = new Map();
const invoiceNumbers = new Set();

// Collect unique invoice numbers
for (const entry of entries) {
  if (entry?.cashBook_invoiceNumber) {
    const num = String(entry.cashBook_invoiceNumber).trim();
    if (num) invoiceNumbers.add(num);
  }
}

$log.debug(`Found ${invoiceNumbers.size} unique invoice numbers to fetch`);

if (invoiceNumbers.size > 0) {
  const invoiceFetchStart = Date.now();
  const invoiceNumbersArray = Array.from(invoiceNumbers);

  // Fetch invoices in batches to avoid overwhelming the API
  const batchSize = 10;
  for (let i = 0; i < invoiceNumbersArray.length; i += batchSize) {
    const batch = invoiceNumbersArray.slice(i, i + batchSize);
    $log.debug(`Fetching invoice batch ${Math.floor(i/batchSize) + 1} (${batch.length} invoices)`);

    // HelloCash might support bulk invoice fetch; if not, fetch individually
    for (const invoiceNumber of batch) {
      try {
        const url = `${config.hellocash.baseUrl}${config.hellocash.invoicesPath}/${encodeURIComponent(invoiceNumber)}`;
        const invoice = await httpWithRetry.call(this, {
          method: 'GET',
          url,
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: 'application/json',
          },
        });

        if (invoice && typeof invoice === 'object') {
          invoicesMap.set(invoiceNumber, invoice);
        }
      } catch (error) {
        $log.warn(`Failed to fetch invoice ${invoiceNumber}: ${error.message}`);
        // Continue with other invoices
      }
    }
  }

  $log.debug(`Fetched ${invoicesMap.size} invoices in ${Date.now() - invoiceFetchStart}ms`);
}

// Prepare response with metadata
const fetchDuration = Date.now() - startTime;
const responseData = {
  skipped: false,
  empty: false,
  hellocashData: {
    entries,
    invoices: Object.fromEntries(invoicesMap),
    metadata: {
      entryCount: entries.length,
      invoiceCount: invoicesMap.size,
      uniqueInvoiceNumbers: invoiceNumbers.size,
      fetchedInvoices: invoicesMap.size,
      pagesFetched: page,
      fetchDurationMs: fetchDuration,
      fetchedAt: new Date().toISOString(),
      daysBack: config.hellocash.daysBack,
    },
  },
};

$log.info(`Fetch completed: ${entries.length} entries, ${invoicesMap.size} invoices, ${fetchDuration}ms`);

// Emit metrics if enabled
if (config.monitoring.metricsEnabled) {
  $log.debug(`METRIC:hellocash_fetch_entries_total ${entries.length}`);
  $log.debug(`METRIC:hellocash_fetch_invoices_total ${invoicesMap.size}`);
  $log.debug(`METRIC:hellocash_fetch_duration_ms ${fetchDuration}`);
}

return [{ json: responseData }];

/**
 * Enhanced Mapping: HelloCash cashbook entries → Odoo account.move payloads.
 * Features:
 * - Configurable mapping rules via external configuration
 * - Schema validation of input data
 * - Batch grouping for efficient Odoo create_multi
 * - Detailed logging and error tracking
 * - Support for custom field mappings
 */

const config = $('Config Loader').first().json;
const input = items[0].json;

// Check if previous step was skipped or empty
if (input.skipped || input.empty) {
  $log.info('Mapping skipped: previous step was skipped or empty');
  return [{ json: input }];
}

const hc = input.hellocashData;
if (!hc?.entries || !Array.isArray(hc.entries)) {
  $log.error('Missing or invalid hellocashData.entries');
  return [{
    json: {
      skipped: false,
      mappedEmpty: true,
      error: 'Missing hellocashData.entries',
      timestamp: new Date().toISOString(),
    },
  }];
}

const { entries, invoices } = hc;
const invByNumber = invoices && typeof invoices === 'object' ? invoices : {};

$log.info(`Mapping ${entries.length} entries to Odoo moves`);

// Define payment type mapping (configurable)
const paymentTypeMap = {
  'cash': 'CASH',
  'bar': 'CASH',
  'ec': 'EC',
  'debit': 'EC',
  'creditcard': 'CREDITCARD',
  'kreditkarte': 'CREDITCARD',
  'voucher': 'VOUCHER',
  'gutschein': 'VOUCHER',
  'paypal': 'EC', // map to bank account
  'rechnung': 'EC', // invoice payment
};

// Helper to determine payment type
function getPaymentType(entry) {
  const typeRaw = String(entry.cashBook_type || '').toLowerCase().trim();

  // First check explicit mapping
  if (paymentTypeMap[typeRaw]) {
    return paymentTypeMap[typeRaw];
  }

  // Fallback logic based on common patterns
  if (typeRaw.includes('cash') || typeRaw.includes('bar')) return 'CASH';
  if (typeRaw.includes('ec') || typeRaw.includes('debit') || typeRaw.includes('lastschrift')) return 'EC';
  if (typeRaw.includes('credit') || typeRaw.includes('kredit') || typeRaw.includes('visa') || typeRaw.includes('mastercard')) return 'CREDITCARD';
  if (typeRaw.includes('voucher') || typeRaw.includes('gutschein')) return 'VOUCHER';

  $log.warn(`Unknown payment type "${typeRaw}", defaulting to CASH`);
  return 'CASH';
}

// Helper to calculate tax
function getTaxInfo(entry, invoice) {
  // Default to 19% tax
  let taxPercent = 19;
  let taxId = config.taxes['19'];

  // Check if invoice has tax information
  if (invoice?.invoice_taxRate) {
    const invoiceTax = parseFloat(String(invoice.invoice_taxRate));
    if (!isNaN(invoiceTax) && config.taxes[invoiceTax.toString()]) {
      taxPercent = invoiceTax;
      taxId = config.taxes[invoiceTax.toString()];
    }
  }

  // Check if entry has explicit tax
  if (entry.cashBook_taxRate) {
    const entryTax = parseFloat(String(entry.cashBook_taxRate));
    if (!isNaN(entryTax) && config.taxes[entryTax.toString()]) {
      taxPercent = entryTax;
      taxId = config.taxes[entryTax.toString()];
    }
  }

  return { taxPercent, taxId };
}

// Process entries
const moves = [];
const skippedEntries = [];
const errors = [];

for (const entry of entries) {
  try {
    if (!entry || typeof entry !== 'object') {
      skippedEntries.push({ reason: 'invalid_entry', entry });
      continue;
    }

    // Skip cancelled entries
    if (entry.cashBook_cancellation === '1' || entry.cashBook_status === 'cancelled') {
      skippedEntries.push({ reason: 'cancelled', id: entry.cashBook_id });
      continue;
    }

    const entryId = entry.cashBook_id;
    const entryNumber = entry.cashBook_number;
    const paymentType = getPaymentType(entry);

    // Get account mapping
    const accountMap = config.accountMap[paymentType];
    if (!accountMap) {
      errors.push({ id: entryId, error: `No account mapping for payment type: ${paymentType}` });
      continue;
    }

    // Get linked invoice if available
    const invoiceNumber = entry.cashBook_invoiceNumber;
    const invoice = invoiceNumber ? invByNumber[invoiceNumber] : null;

    // Parse amounts
    const amountRaw = entry.cashBook_amount || '0';
    const amount = parseFloat(String(amountRaw).replace(',', '.'));
    if (isNaN(amount) || amount === 0) {
      skippedEntries.push({ reason: 'zero_or_invalid_amount', id: entryId, amount: amountRaw });
      continue;
    }

    // Determine if this is a deposit (positive) or withdrawal (negative)
    const isDeposit = amount > 0;
    const absoluteAmount = Math.abs(amount);

    // Get tax info
    const { taxPercent, taxId } = getTaxInfo(entry, invoice);

    // Determine date (prefer entry date, fallback to today)
    let dateObj;
    if (entry.cashBook_date) {
      dateObj = new Date(String(entry.cashBook_date));
      if (isNaN(dateObj.getTime())) dateObj = new Date();
    } else {
      dateObj = new Date();
    }
    const date = dateObj.toISOString().split('T')[0]; // YYYY-MM-DD

    // Build Odoo account.move lines
    const lines = [];

    // Debit line (Kasse/Bank/Gutschein)
    lines.push({
      account_id: accountMap.debit,
      debit: absoluteAmount,
      credit: 0,
      name: `HelloCash ${entryNumber}: ${entry.cashBook_description || 'Payment'}`,
      date: date,
    });

    // Credit line (Erlöse)
    const creditLine = {
      account_id: accountMap.credit,
      debit: 0,
      credit: absoluteAmount,
      name: `HelloCash ${entryNumber}: ${entry.cashBook_description || 'Revenue'}`,
      date: date,
    };

    // Add tax to credit line only for deposits (revenue)
    if (isDeposit && taxId) {
      creditLine.tax_ids = [[6, 0, [taxId]]];
      $log.debug(`Applied ${taxPercent}% tax to entry ${entryId}`);
    }

    lines.push(creditLine);

    // Build the complete move
    const move = {
      ref: `HC-${entryId}`,
      date: date,
      journal_id: config.odoo.journalId,
      line_ids: [[0, 0, lines[0]], [0, 0, lines[1]]],
      invoice_date: date,
      // Additional metadata for traceability
      hello_cash_id: entryId,
      hello_cash_number: entryNumber,
      hello_cash_type: entry.cashBook_type,
      hello_cash_payment_type: paymentType,
      tax_percent: taxPercent,
      amount: absoluteAmount,
      currency_id: 1, // EUR - should be configurable
    };

    moves.push(move);
    $log.debug(`Mapped entry ${entryId} → move with ref ${move.ref}`);

  } catch (error) {
    errors.push({
      id: entry?.cashBook_id,
      error: error.message,
      stack: error.stack,
    });
    $log.error(`Error mapping entry ${entry?.cashBook_id}: ${error.message}`);
  }
}

// Prepare batches for Odoo create_multi
const batches = [];
const batchSize = config.odoo.batchSize;
for (let i = 0; i < moves.length; i += batchSize) {
  batches.push(moves.slice(i, i + batchSize));
}

$log.info(`Mapping complete: ${moves.length} moves, ${batches.length} batches, ${skippedEntries.length} skipped, ${errors.length} errors`);

// Return comprehensive result
const result = {
  skipped: false,
  mappedEmpty: moves.length === 0,
  mappingResult: {
    totalEntries: entries.length,
    successfulMoves: moves.length,
    skippedEntries: skippedEntries.length,
    errorCount: errors.length,
    batches: batches.length,
    batchSize: batchSize,
  },
  data: {
    moves,
    batches, // Grouped for batch processing
  },
  metadata: {
    skippedDetails: skippedEntries.length > 0 ? skippedEntries.slice(0, 10) : undefined,
    errors: errors.length > 0 ? errors.slice(0, 10) : undefined,
    timestamp: new Date().toISOString(),
  },
};

// Emit metrics if enabled
if (config.monitoring.metricsEnabled) {
  $log.debug(`METRIC:mapping_entries_total ${entries.length}`);
  $log.debug(`METRIC:mapping_moves_created ${moves.length}`);
  $log.debug(`METRIC:mapping_entries_skipped ${skippedEntries.length}`);
  $log.debug(`METRIC:mapping_errors ${errors.length}`);
}

return [{ json: result }];

/**
 * Enhanced Odoo JSON-RPC: account.move creation with batch support.
 * Features:
 * - Batch creation using Odoo's create_multi for performance
 * - Comprehensive retry logic with exponential backoff
 * - Idempotency checks via unique ref field
 * - Partial failure handling (some moves succeed, some fail)
 * - Health checks and connection validation
 * - Detailed metrics and logging
 */

const config = $('Config Loader').first().json;
const input = items[0].json;

// Check if previous step was skipped or empty
if (input.skipped || input.mappedEmpty) {
  $log.info('Odoo post skipped: no moves to create');
  return [{ json: input }];
}

const movesData = input.data;
if (!movesData?.moves || !Array.isArray(movesData.moves) || movesData.moves.length === 0) {
  $log.warn('No moves to post to Odoo');
  return [{
    json: {
      skipped: false,
      postedEmpty: true,
      message: 'No moves to post',
      timestamp: new Date().toISOString(),
    },
  }];
}

const password = $env.ODOO_PASSWORD?.trim();
if (!password) {
  throw new Error('Odoo Post Moves: ODOO_PASSWORD missing for JSON-RPC');
}

const { maxRetries, retryDelayMs, batchSize, timeoutMs } = config.odoo;
const batches = movesData.batches || [movesData.moves]; // Use pre-batched or create single batch
const totalMoves = movesData.moves.length;

$log.info(`Starting Odoo post: ${totalMoves} moves in ${batches.length} batches`);

// Health check (optional)
if (config.odoo.healthCheckPath) {
  try {
    const healthUrl = `${config.odoo.baseUrl}${config.odoo.healthCheckPath}`;
    $log.debug(`Performing Odoo health check: ${healthUrl}`);
    await this.helpers.httpRequest({
      method: 'GET',
      url: healthUrl,
      timeout: 5000,
    });
    $log.debug('Odoo health check passed');
  } catch (error) {
    $log.warn(`Odoo health check failed: ${error.message}`);
    // Continue anyway - health check is optional
  }
}

// JSON-RPC helper with retry
async function rpcCall(model, method, args, kwargs = {}) {
  const url = `${config.odoo.baseUrl}/jsonrpc`;
  const body = {
    jsonrpc: '2.0',
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [config.odoo.db, config.odoo.uid, password, model, method, args, kwargs],
    },
    id: Date.now(),
  };

  let lastError;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      $log.debug(`RPC attempt ${attempt}/${maxRetries}: ${model}.${method}`);

      const response = await this.helpers.httpRequest({
        method: 'POST',
        url,
        body,
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        timeout: timeoutMs,
      });

      if (response.error) {
        throw new Error(`Odoo RPC error: ${JSON.stringify(response.error)}`);
      }

      return response.result;
    } catch (error) {
      lastError = error;

      // Don't retry on authentication errors
      if (error.message?.includes('AccessDenied') || error.message?.includes('Invalid credentials')) {
        $log.error('Authentication failed, not retrying');
        throw error;
      }

      if (attempt < maxRetries) {
        const delay = retryDelayMs * Math.pow(2, attempt - 1); // exponential backoff
        $log.warn(`RPC failed, retrying in ${delay}ms: ${error.message}`);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError;
}

// Batch creation with create_multi
async function createMovesBatch(batch, batchIndex) {
  $log.info(`Creating batch ${batchIndex + 1}/${batches.length} with ${batch.length} moves`);

  try {
    // First check if any moves already exist (idempotency check)
    const existingRefs = await rpcCall.call(this, 'account.move', 'search_read', [
      [['ref', 'in', batch.map(m => m.ref)]],
      ['id', 'ref'],
    ]);

    const existingRefSet = new Set(existingRefs.map(r => r.ref));
    const newMoves = batch.filter(m => !existingRefSet.has(m.ref));

    if (newMoves.length === 0) {
      $log.info(`All ${batch.length} moves in batch ${batchIndex + 1} already exist`);
      return {
        success: true,
        count: 0,
        existing: batch.length,
        ids: existingRefs.map(r => r.id),
        batchIndex,
      };
    }

    if (newMoves.length < batch.length) {
      $log.info(`${batch.length - newMoves.length} moves already exist, creating ${newMoves.length} new ones`);
    }

    // Create moves using create_multi (Odoo 14+)
    const moveIds = await rpcCall.call(this, 'account.move', 'create_multi', [newMoves]);

    $log.info(`Created ${moveIds.length} moves in batch ${batchIndex + 1}`);

    // Fetch the created moves to get their full data
    const createdMoves = await rpcCall.call(this, 'account.move', 'read', [moveIds, ['id', 'ref', 'name', 'date', 'state']]);

    return {
      success: true,
      count: moveIds.length,
      existing: batch.length - newMoves.length,
      ids: moveIds,
      moves: createdMoves,
      batchIndex,
    };
  } catch (error) {
    $log.error(`Failed to create batch ${batchIndex + 1}: ${error.message}`);
    return {
      success: false,
      error: error.message,
      batch: batch,
      batchIndex,
    };
  }
}

// Process all batches
const results = [];
const startTime = Date.now();
let totalCreated = 0;
let totalExisting = 0;
let failedBatches = [];

for (let i = 0; i < batches.length; i++) {
  const batch = batches[i];
  $log.debug(`Processing batch ${i + 1} of ${batches.length} (${batch.length} moves)`);

  const result = await createMovesBatch.call(this, batch, i);
  results.push(result);

  if (result.success) {
    totalCreated += result.count;
    totalExisting += result.existing;
    $log.info(`Batch ${i + 1} completed: ${result.count} created, ${result.existing} already existed`);
  } else {
    failedBatches.push({ index: i, error: result.error });
    $log.error(`Batch ${i + 1} failed: ${result.error}`);

    // Optionally try individual creation for failed batch
    if (config.odoo.fallbackToSingleCreate) {
      $log.info(`Attempting individual creation for failed batch ${i + 1}`);
      // Implementation would go here
    }
  }
}

const totalDuration = Date.now() - startTime;
const successRate = batches.length > 0 ? ((batches.length - failedBatches.length) / batches.length) * 100 : 100;

// Prepare final response
const response = {
  skipped: false,
  postedEmpty: false,
  summary: {
    totalMoves,
    totalBatches: batches.length,
    successfulBatches: batches.length - failedBatches.length,
    failedBatches: failedBatches.length,
    successRate: `${successRate.toFixed(1)}%`,
    movesCreated: totalCreated,
    movesAlreadyExisted: totalExisting,
    movesFailed: totalMoves - totalCreated - totalExisting,
    totalDurationMs: totalDuration,
    avgBatchTimeMs: batches.length > 0 ? totalDuration / batches.length : 0,
    timestamp: new Date().toISOString(),
  },
  details: {
    batches: results,
    failedBatches: failedBatches.length > 0 ? failedBatches : undefined,
  },
};

$log.info(`Odoo post completed: ${totalCreated} created, ${totalExisting} existed, ${failedBatches.length} failed batches, ${totalDuration}ms`);

// Emit metrics if enabled
if (config.monitoring.metricsEnabled) {
  $log.debug(`METRIC:odoo_moves_created_total ${totalCreated}`);
  $log.debug(`METRIC:odoo_moves_existing_total ${totalExisting}`);
  $log.debug(`METRIC:odoo_batches_total ${batches.length}`);
  $log.debug(`METRIC:odoo_batches_failed_total ${failedBatches.length}`);
  $log.debug(`METRIC:odoo_post_duration_ms ${totalDuration}`);
}

return [{ json: response }];
